/**
 * Compares two OpenAPI 3.0.3 documents and lists every change in `head`
 * that would break a client built against `base` — the shipped iOS app
 * (ios/Sources/ReadingRigKit, generated by swift-openapi-generator from a
 * symlink to openapi/api-v1.json) and API-token agents. Pure: no I/O, so
 * scripts/checkOpenApiCompat.ts owns git and the filesystem.
 *
 * "Breaking" is judged against what that generated Swift client actually
 * does, not generic OpenAPI folklore. Two consequences that look stricter
 * than usual, both confirmed in its generated Types.swift:
 *
 *  - Response objects declared `additionalProperties: false` (every
 *    z.object() response in this API) decode through
 *    `ensureNoAdditionalProperties(knownKeys:)`, which throws on any key it
 *    wasn't built with. So a *new response property* on such an object
 *    breaks installed builds — it is not the safe additive change it is
 *    for most JSON clients.
 *  - String enums are generated `@frozen`, so a response enum *gaining* a
 *    value fails to decode on installed builds.
 *
 * Request-side rules are the usual ones: the server must keep accepting
 * everything an old client sends.
 */

export type BreakingChangeKind =
  | "removed-path"
  | "removed-method"
  | "operation-id-changed"
  | "security-changed"
  | "removed-response-status"
  | "removed-response-media-type"
  | "removed-response-property"
  | "added-response-property-closed-object"
  | "response-property-became-optional"
  | "response-became-nullable"
  | "response-type-changed"
  | "response-enum-lost-value"
  | "response-enum-gained-value"
  | "response-added-variant"
  | "new-required-parameter"
  | "parameter-became-required"
  | "request-type-changed"
  | "request-enum-lost-value"
  | "new-required-request-body"
  | "removed-request-media-type"
  | "new-required-request-property"
  | "request-property-became-required"
  | "request-removed-variant";

export type BreakingChange = {
  /** e.g. "GET /api/v1/home 200 application/json .works[].title" */
  path: string;
  kind: BreakingChangeKind;
  detail: string;
};

type Json = Record<string, unknown>;

const HTTP_METHODS = [
  "get",
  "put",
  "post",
  "delete",
  "patch",
  "head",
  "options",
  "trace",
] as const;

function isObject(value: unknown): value is Json {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function obj(value: unknown): Json {
  return isObject(value) ? value : {};
}

function arr(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function stringList(value: unknown): string[] {
  return arr(value).filter((v): v is string => typeof v === "string");
}

/**
 * Replaces every local `#/...` $ref with (a deep copy of) its target, so the
 * comparison below never has to know refs exist. A ref that points back into
 * its own ancestry is left as-is rather than expanded forever.
 */
export function resolveLocalRefs<T>(doc: T): T {
  const root = doc as unknown;
  function lookup(ref: string): unknown {
    let node: unknown = root;
    for (const raw of ref.slice(2).split("/")) {
      const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");
      node = obj(node)[key];
      if (node === undefined) throw new Error(`Unresolvable $ref ${ref}`);
    }
    return node;
  }
  function walk(node: unknown, active: Set<string>): unknown {
    if (Array.isArray(node)) return node.map((n) => walk(n, active));
    if (!isObject(node)) return node;
    const ref = node.$ref;
    if (typeof ref === "string" && ref.startsWith("#/")) {
      if (active.has(ref)) return node;
      return walk(lookup(ref), new Set([...active, ref]));
    }
    const out: Json = {};
    for (const [key, value] of Object.entries(node)) {
      out[key] = walk(value, active);
    }
    return out;
  }
  return walk(doc, new Set()) as T;
}

/** "/read/{workId}" and "/read/{id}" are the same route to a client. */
function normalizePathTemplate(path: string): string {
  return path.replace(/\{[^}]+\}/g, "{}");
}

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (isObject(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function typeOf(schema: Json): string | undefined {
  if (typeof schema.type === "string") return schema.type;
  if (isObject(schema.properties)) return "object";
  if (schema.items !== undefined) return "array";
  return undefined;
}

function enumValues(schema: Json): unknown[] | undefined {
  return Array.isArray(schema.enum) ? schema.enum : undefined;
}

function missingFrom(from: unknown[], into: unknown[]): unknown[] {
  const present = new Set(into.map(canonical));
  return from.filter((v) => !present.has(canonical(v)));
}

/**
 * A stable identity for a oneOf/anyOf member: its required, single-valued
 * enum properties (the discriminator, in practice — `intent`, `kind`), falling
 * back to position when a variant has none.
 */
function variantKeys(variants: unknown[]): string[] {
  return variants.map((variant, index) => {
    const props = obj(obj(variant).properties);
    const tags = stringList(obj(variant).required)
      .filter((name) => name in props)
      .sort()
      .flatMap((name) => {
        const values = enumValues(obj(props[name]));
        return values?.length === 1
          ? [`${name}=${JSON.stringify(values[0])}`]
          : [];
      });
    return tags.length > 0 ? tags.join("&") : `#${index}`;
  });
}

function unionMembers(schema: Json): unknown[] | undefined {
  if (Array.isArray(schema.oneOf)) return schema.oneOf;
  if (Array.isArray(schema.anyOf)) return schema.anyOf;
  return undefined;
}

type Report = (path: string, kind: BreakingChangeKind, detail: string) => void;

/**
 * What a client *receives*: anything it was built to read must still arrive,
 * in the same shape, and nothing it can't decode may appear.
 */
function compareResponseSchema(
  base: Json,
  head: Json,
  at: string,
  report: Report,
): void {
  const baseType = typeOf(base);
  const headType = typeOf(head);
  if (baseType && baseType !== headType) {
    report(
      at,
      "response-type-changed",
      `type ${baseType} → ${headType ?? "unconstrained"}`,
    );
    return;
  }
  if (base.nullable !== true && head.nullable === true) {
    report(at, "response-became-nullable", "can now be null");
  }

  const baseEnum = enumValues(base);
  const headEnum = enumValues(head);
  if (baseEnum) {
    const lost = headEnum ? missingFrom(baseEnum, headEnum) : [];
    if (lost.length > 0) {
      report(
        at,
        "response-enum-lost-value",
        `enum no longer includes ${lost.map((v) => JSON.stringify(v)).join(", ")}`,
      );
    }
    const gained = headEnum ? missingFrom(headEnum, baseEnum) : [];
    if (gained.length > 0 || !headEnum) {
      report(
        at,
        "response-enum-gained-value",
        headEnum
          ? `enum gained ${gained.map((v) => JSON.stringify(v)).join(", ")} — installed clients decode enums as @frozen`
          : "enum constraint removed — installed clients decode enums as @frozen",
      );
    }
  }

  const baseUnion = unionMembers(base);
  const headUnion = unionMembers(head);
  if (baseUnion && headUnion) {
    const baseKeys = variantKeys(baseUnion);
    const headKeys = variantKeys(headUnion);
    headKeys.forEach((key, i) => {
      const j = baseKeys.indexOf(key);
      if (j === -1) {
        report(at, "response-added-variant", `new oneOf variant ${key}`);
      } else {
        compareResponseSchema(
          obj(baseUnion[j]),
          obj(headUnion[i]),
          `${at}<${key}>`,
          report,
        );
      }
    });
  }

  if (baseType === "array") {
    compareResponseSchema(obj(base.items), obj(head.items), `${at}[]`, report);
  }

  if (baseType === "object") {
    const baseProps = obj(base.properties);
    const headProps = obj(head.properties);
    const baseRequired = new Set(stringList(base.required));
    const headRequired = new Set(stringList(head.required));
    for (const name of Object.keys(baseProps)) {
      const propAt = `${at}.${name}`;
      if (!(name in headProps)) {
        report(propAt, "removed-response-property", "property removed");
        continue;
      }
      if (baseRequired.has(name) && !headRequired.has(name)) {
        report(
          propAt,
          "response-property-became-optional",
          "was required, now optional",
        );
      }
      compareResponseSchema(
        obj(baseProps[name]),
        obj(headProps[name]),
        propAt,
        report,
      );
    }
    if (base.additionalProperties === false) {
      for (const name of Object.keys(headProps)) {
        if (!(name in baseProps)) {
          report(
            `${at}.${name}`,
            "added-response-property-closed-object",
            "new property on an additionalProperties:false object — installed clients reject unknown keys",
          );
        }
      }
    }
  }
}

/**
 * What a client *sends*: everything an old client sends must still be
 * accepted, and nothing new may be demanded of it.
 */
function compareRequestSchema(
  base: Json,
  head: Json,
  at: string,
  report: Report,
): void {
  const baseType = typeOf(base);
  const headType = typeOf(head);
  if (headType && baseType !== headType) {
    report(
      at,
      "request-type-changed",
      `type ${baseType ?? "unconstrained"} → ${headType}`,
    );
    return;
  }

  const baseEnum = enumValues(base);
  const headEnum = enumValues(head);
  if (headEnum) {
    const lost = baseEnum ? missingFrom(baseEnum, headEnum) : [];
    if (!baseEnum || lost.length > 0) {
      report(
        at,
        "request-enum-lost-value",
        baseEnum
          ? `enum no longer accepts ${lost.map((v) => JSON.stringify(v)).join(", ")}`
          : "newly constrained to an enum",
      );
    }
  }

  const baseUnion = unionMembers(base);
  const headUnion = unionMembers(head);
  if (baseUnion && headUnion) {
    const baseKeys = variantKeys(baseUnion);
    const headKeys = variantKeys(headUnion);
    baseKeys.forEach((key, i) => {
      const j = headKeys.indexOf(key);
      if (j === -1) {
        report(at, "request-removed-variant", `oneOf variant ${key} removed`);
      } else {
        compareRequestSchema(
          obj(baseUnion[i]),
          obj(headUnion[j]),
          `${at}<${key}>`,
          report,
        );
      }
    });
  }

  if (headType === "array") {
    compareRequestSchema(obj(base.items), obj(head.items), `${at}[]`, report);
  }

  if (headType === "object") {
    const baseProps = obj(base.properties);
    const headProps = obj(head.properties);
    const baseRequired = new Set(stringList(base.required));
    for (const name of stringList(head.required)) {
      if (!(name in baseProps)) {
        report(
          `${at}.${name}`,
          "new-required-request-property",
          "new required property",
        );
      } else if (!baseRequired.has(name)) {
        report(
          `${at}.${name}`,
          "request-property-became-required",
          "was optional, now required",
        );
      }
    }
    for (const name of Object.keys(headProps)) {
      if (name in baseProps) {
        compareRequestSchema(
          obj(baseProps[name]),
          obj(headProps[name]),
          `${at}.${name}`,
          report,
        );
      }
    }
  }
}

function effectiveParameters(
  pathItem: Json,
  operation: Json,
): Map<string, Json> {
  const params = new Map<string, Json>();
  for (const p of [...arr(pathItem.parameters), ...arr(operation.parameters)]) {
    const param = obj(p);
    params.set(`${String(param.in)}:${String(param.name)}`, param);
  }
  return params;
}

/**
 * The operation's security requirements — alternatives, any one of which
 * satisfies it — each canonicalized with its schemes' definitions inlined,
 * so a renamed cookie counts as a different requirement.
 */
function securityAlternatives(doc: Json, operation: Json): string[] {
  const requirements = arr(operation.security ?? doc.security);
  const schemes = obj(obj(doc.components).securitySchemes);
  return requirements.map((req) =>
    canonical(
      Object.fromEntries(
        Object.entries(obj(req)).map(([name, scopes]) => [
          name,
          { scopes, scheme: schemes[name] ?? null },
        ]),
      ),
    ),
  );
}

export function findBreakingChanges(
  baseDoc: unknown,
  headDoc: unknown,
): BreakingChange[] {
  const base = resolveLocalRefs(obj(baseDoc));
  const head = resolveLocalRefs(obj(headDoc));
  const findings: BreakingChange[] = [];
  const report: Report = (path, kind, detail) =>
    findings.push({ path, kind, detail });

  const headPaths = new Map(
    Object.entries(obj(head.paths)).map(([p, item]) => [
      normalizePathTemplate(p),
      obj(item),
    ]),
  );

  for (const [path, rawBaseItem] of Object.entries(obj(base.paths))) {
    const baseItem = obj(rawBaseItem);
    const headItem = headPaths.get(normalizePathTemplate(path));
    if (!headItem) {
      report(path, "removed-path", "path removed");
      continue;
    }

    for (const method of HTTP_METHODS) {
      if (!(method in baseItem)) continue;
      const op = `${method.toUpperCase()} ${path}`;
      const baseOp = obj(baseItem[method]);
      if (!(method in headItem)) {
        report(op, "removed-method", "operation removed");
        continue;
      }
      const headOp = obj(headItem[method]);

      if (
        baseOp.operationId !== undefined &&
        baseOp.operationId !== headOp.operationId
      ) {
        report(
          op,
          "operation-id-changed",
          `operationId ${String(baseOp.operationId)} → ${String(headOp.operationId)} — renames the generated Swift method`,
        );
      }

      // Adding an alternative is additive; an old client still satisfies
      // whichever one it was built for. Losing or altering one is not.
      // (No requirements at all means "open", which nothing old can fail.)
      const headSecurity = securityAlternatives(head, headOp);
      if (headSecurity.length > 0) {
        const lost = securityAlternatives(base, baseOp).filter(
          (alt) => !headSecurity.includes(alt),
        );
        if (
          lost.length > 0 ||
          securityAlternatives(base, baseOp).length === 0
        ) {
          report(
            op,
            "security-changed",
            lost.length > 0
              ? `security alternative(s) removed or changed: ${lost.join(" | ")}`
              : "previously unauthenticated operation now requires auth",
          );
        }
      }

      // Parameters.
      const baseParams = effectiveParameters(baseItem, baseOp);
      for (const [key, headParam] of effectiveParameters(headItem, headOp)) {
        const at = `${op} param ${key}`;
        const baseParam = baseParams.get(key);
        if (!baseParam) {
          if (headParam.required === true) {
            report(at, "new-required-parameter", "new required parameter");
          }
          continue;
        }
        if (baseParam.required !== true && headParam.required === true) {
          report(at, "parameter-became-required", "was optional, now required");
        }
        compareRequestSchema(
          obj(baseParam.schema),
          obj(headParam.schema),
          at,
          report,
        );
      }

      // Request body.
      const baseBody = isObject(baseOp.requestBody) ? baseOp.requestBody : null;
      const headBody = isObject(headOp.requestBody) ? headOp.requestBody : null;
      if (!baseBody && headBody?.required === true) {
        report(
          `${op} requestBody`,
          "new-required-request-body",
          "operation now requires a body",
        );
      } else if (baseBody && headBody) {
        const headContent = obj(headBody.content);
        for (const [mediaType, baseMedia] of Object.entries(
          obj(baseBody.content),
        )) {
          const at = `${op} requestBody ${mediaType}`;
          if (!(mediaType in headContent)) {
            report(
              at,
              "removed-request-media-type",
              "media type no longer accepted",
            );
            continue;
          }
          compareRequestSchema(
            obj(obj(baseMedia).schema),
            obj(obj(headContent[mediaType]).schema),
            at,
            report,
          );
        }
      }

      // Responses.
      const headResponses = obj(headOp.responses);
      for (const [status, baseResponse] of Object.entries(
        obj(baseOp.responses),
      )) {
        const at = `${op} ${status}`;
        if (!(status in headResponses)) {
          report(at, "removed-response-status", "response status removed");
          continue;
        }
        const headContent = obj(obj(headResponses[status]).content);
        for (const [mediaType, baseMedia] of Object.entries(
          obj(obj(baseResponse).content),
        )) {
          if (!(mediaType in headContent)) {
            report(
              `${at} ${mediaType}`,
              "removed-response-media-type",
              "media type no longer returned",
            );
            continue;
          }
          compareResponseSchema(
            obj(obj(baseMedia).schema),
            obj(obj(headContent[mediaType]).schema),
            `${at} ${mediaType}`,
            report,
          );
        }
      }
    }
  }

  return findings;
}

/**
 * True when any commit message carries an `API-Breaking-Change: <reason>`
 * trailer with a non-empty reason — the explicit, reviewed override.
 */
export function hasBreakingChangeTrailer(commitMessages: string): boolean {
  return /^API-Breaking-Change:[ \t]*\S/m.test(commitMessages);
}
